import pytest

def dividir(a, b):
    if b == 0:
        raise ValueError("Divisor no puede ser 0")
    return a / b

def test_division_correcta():
    assert dividir(10, 2) == 5.0

def test_division_por_cero():
    with pytest.raises(ValueError):
        dividir(10, 0)

